    public void emit_sources(RefCounted controller,string id,Settings state,Settings v,double time,double dt)
    {
        int n=state["fog_n"].AsInt32();var points=_solver.grid(n)["positions"].AsVector3Array();var domain=state["fog_pose"].AsTransform3D();var inverse=domain.AffineInverse();double local=Local(controller,id,time);var dimensions=state["fog_size"].AsVector3();var previousSources=state["fog_source_previous"].AsGodotDictionary();var bursts=state["fog_bursts"].AsGodotDictionary();
        for(int slot=0;slot<4;slot++){var resource=Resolve(v.GetValueOrDefault("fog_source_"+slot,default(Variant)));if(resource==null)continue;var source=resource.Get("values").AsGodotDictionary();if(!source.GetValueOrDefault("enabled",true).AsBool())continue;var pose=source_pose(controller,id,source,time);var previous=previousSources.GetValueOrDefault(slot,pose).AsTransform3D();previousSources[slot]=pose;double start=N(source,"start"),end=N(source,"end",-1),mass=0;if((int)N(source,"mode")==1){if(local>=start&&!bursts.ContainsKey(slot)){bursts[slot]=true;if(dt>0&&local-dt<start+.000001||Mathf.IsEqualApprox(local,start))mass=N(source,"burst",1);}}else mass=N(source,"rate",.2)*Math.Max(0,Math.Min(local,end>=0?end:local)-Math.Max(local-dt,start));if(mass<=0)continue;
            var cells=new List<int>();var weights=new List<float>();int kind=(int)N(source,"shape",1);var sourceSize=V(source,"size",Vector3.One*.5f).Abs().Max(Vector3.One*.001f);var sourceInverse=pose.AffineInverse();float padding=dimensions.Length()/n*.5f;var mesh=new Godot.Collections.Array<Image>();if(kind is 3 or 4){var direction=V(source,"direction",Vector3.Up);if(!direction.IsZeroApprox())sourceInverse=(pose*new Transform3D(new Basis(new Quaternion(Vector3.Up,direction.Normalized())),Vector3.Zero)).AffineInverse();}if(kind==5){var volume=_mesh.prepare(source.GetValueOrDefault("mesh","").AsString());foreach(var image in volume.GetValueOrDefault("slices",new GArray()).AsGodotArray())mesh.Add(image.As<Image>());string error=volume.GetValueOrDefault("error","").AsString();if(error.Length>0)controller.Call("_warn","Fog source: "+error);}
