            var velocity=pose.Basis.Orthonormalized()*V(source,"velocity",Vector3.Up);if(source.GetValueOrDefault("inherit_velocity",true).AsBool()&&dt>0)velocity+=(pose.Origin-previous.Origin)/(float)dt;double spread=N(source,"spread")*Math.PI/180;if(spread<=0||cells.Count==0)_solver.inject(state,cells.ToArray(),weights.ToArray(),mass,domain.Basis.Inverse()*velocity);else{double sum=0;var solid=state["fog_solid"].AsByteArray();for(int i=0;i<cells.Count;i++)if(solid[cells[i]]==0)sum+=weights[i];var rng=new RandomNumberGenerator{Seed=unchecked((ulong)(uint)GD.Hash(new GArray{(int)N(source,"seed",1),slot,state["fog_step"]}))};var varied=new Vector3[cells.Count];for(int i=0;i<cells.Count;i++){if(solid[cells[i]]!=0||sum<=0)continue;var direction=velocity.Normalized();var axis=direction.Cross(Math.Abs(direction.Y)<.9?Vector3.Up:Vector3.Right).Normalized();var tilted=direction.Rotated(axis,(float)Math.Acos(Mathf.Lerp(Math.Cos(spread),1,rng.Randf()))).Rotated(direction,rng.Randf()*Mathf.Tau);varied[i]=domain.Basis.Inverse()*tilted*velocity.Length();}_solver.InjectVaried(state,cells,weights,mass,varied);}
        }
    }
    public void obstacles(RefCounted controller,string id,Settings state,Settings v,double dt)
    {
        int n=state["fog_n"].AsInt32();var points=_solver.grid(n)["positions"].AsVector3Array();var solid=new byte[points.Length];var boundary=new Vector3[points.Length];var previous=state["fog_obstacle_previous"].AsGodotDictionary();var next=new Settings();var domain=state["fog_pose"].AsTransform3D();var dimensions=state["fog_size"].AsVector3();if(v.GetValueOrDefault("fog_obstacles",true).AsBool()){
            var sets=new List<Settings>{controller.Get("world").AsGodotObject().Get("bodies").AsGodotDictionary()};if(v.GetValueOrDefault("fog_character_proxies",true).AsBool())sets.Add(controller.Get("fluid").AsGodotObject().Get("proxies").AsGodotObject().Get("bodies").AsGodotDictionary());foreach(var entries in sets)foreach(var item in entries){string key=item.Key.AsString();var entry=item.Value.AsGodotDictionary();if(key==id||key.StartsWith("@probe:",StringComparison.Ordinal)||!entry.GetValueOrDefault("enabled",false).AsBool())continue;var pose=entry.GetValueOrDefault("pose",Transform3D.Identity).AsTransform3D();var before=previous.GetValueOrDefault(key,pose).AsTransform3D();next[key]=pose;var velocity=dt>0?(pose.Origin-before.Origin)/(float)dt:Vector3.Zero;foreach(var element in entry.GetValueOrDefault("compound",new GArray{new Settings{["shape"]=entry["shape"],["offset"]=entry["offset"]}}).AsGodotArray()){var part=element.AsGodotDictionary();var shape=part["shape"].As<Shape3D>();var transform=pose*part["offset"].AsTransform3D();if(Math.Abs(transform.Basis.Determinant())<.000001)continue;var box=bounds(shape);if(box.Size.IsZeroApprox()){controller.Call("_warn","Fog obstacles support primitives and conservative convex bounds. Use compound convex colliders for mesh openings.");continue;}var inverse=transform.AffineInverse();var padding=Vector3.One/transform.Basis.Scale.Abs()*dimensions/n*.5f;var toDomain=domain.AffineInverse()*transform;var region=new Aabb(toDomain*box.Position,Vector3.Zero);for(int corner=0;corner<8;corner++)region=region.Expand(toDomain*(box.Position+box.Size*new Vector3(corner&1,(corner>>1)&1,(corner>>2)&1)));var low=((region.Position/dimensions+Vector3.One*.5f)*n-Vector3.One*.5f).Floor().Max(Vector3.Zero);var high=((region.End/dimensions+Vector3.One*.5f)*n+Vector3.One*.5f).Ceil().Min(Vector3.One*(n-1));for(int z=(int)low.Z;z<=(int)high.Z;z++)for(int y=(int)low.Y;y<=(int)high.Y;y++)for(int x=(int)low.X;x<=(int)high.X;x++){int i=x+n*(y+n*z);var world=domain*(points[i]*dimensions);if(contains(shape,inverse*world,padding)){solid[i]=1;boundary[i]=domain.Basis.Inverse()*velocity*(float)N(v,"fog_obstacle_motion",1);}}}}}
        state["fog_obstacle_previous"]=next;_solver.set_obstacles(state,solid,boundary);
    }
    public void step(RefCounted controller,string id,Settings state,Settings config,double time,double dt)
    {
        ulong started=Time.GetTicksUsec();var v=values(controller,id,time);var world=controller.Call("animated_world",id,time,true,new Settings()).AsTransform3D();var dimensions=V(v,"volume_size",new Vector3(4,2,4)).Abs()*world.Basis.Scale.Abs();if(_definition.resolution(v)!=state["fog_n"].AsInt32()||!dimensions.Max(Vector3.One*.01f).IsEqualApprox(state["fog_size"].AsVector3())){initialize(controller,id,state,config,time);controller.Call("_warn","Fog domain dimensions or resolution changed; concentration restarted.");}if((int)N(v,"fog_domain_behavior")==1)state["fog_pose"]=new Transform3D(world.Basis.Orthonormalized(),world.Origin);obstacles(controller,id,state,v,dt);emit_sources(controller,id,state,v,time,dt);var fields=new GArray();var domain=state["fog_pose"].AsTransform3D();var inverse=domain.Basis.Inverse();for(int slot=0;slot<4;slot++){var resource=Resolve(v.GetValueOrDefault("fog_velocity_"+slot,default(Variant)));if(resource==null)continue;var source=resource.Get("values").AsGodotDictionary();var pose=source_pose(controller,id,source,time);var f=source.Duplicate();f["center"]=domain.AffineInverse()*pose.Origin;f["direction"]=inverse*pose.Basis*V(source,"direction",Vector3.Up);fields.Add(f);}double frequency=N(v,"fog_gust_frequency",1),gust=1+N(v,"fog_gust_strength")*Math.Sin(N(state,"fog_time")*frequency);var events=controller.Call("_events",config,Local(controller,id,time),dt).AsGodotDictionary();var eventImpulse=events["impulse"].AsVector3();if(!eventImpulse.IsZeroApprox()){var velocity=state["fog_velocity"].AsVector3Array();var solid=state["fog_solid"].AsByteArray();var impulse=inverse*eventImpulse;for(int i=0;i<velocity.Length;i++)if(solid[i]==0)velocity[i]+=impulse;state["fog_velocity"]=velocity;}var wind=V(v,"fog_wind",Vector3.Zero)*(float)(N(v,"fog_wind_influence",1)*gust)+config["wind"].AsVector3();var force=events["force"].AsVector3();if(!force.IsZeroApprox())fields.Add(new Settings{["center"]=Vector3.Zero,["radius"]=100000.0,["direction"]=inverse*force,["strength"]=1.0,["falloff"]=0.0});var options=new Settings{["wind"]=inverse*wind,["fields"]=fields,["buoyancy_direction"]=inverse*Vector3.Up,["closed"]=(int)N(v,"fog_boundaries")==1};foreach(var pair in new[]{("damping","fog_velocity_damping"),("turbulence","fog_turbulence"),("turbulence_scale","fog_turbulence_scale"),("turbulence_frequency","fog_turbulence_frequency"),("seed","fog_seed"),("buoyancy","fog_buoyancy"),("pressure_iterations","fog_pressure_iterations"),("expansion","fog_expansion"),("diffusion","fog_diffusion"),("dissipation","fog_dissipation"),("max_density","fog_max_density")})options[pair.Item1]=v.GetValueOrDefault(pair.Item2,0.0);_solver.step(state,options,dt);state["fog_cpu_ms"]=(Time.GetTicksUsec()-started)/1000.0;if(state["fog_clamped"].AsBool())controller.Call("_warn","Fog speed reached this grid's stable transport limit. Increase fixed steps or lower velocity / expansion.");
    }
